-- IMEX LOGISTICS V6 — migration légère depuis Nairi V4/V5\n-- Conserve les tables et les données existantes.\n\nupdate public.staff_profiles\nset branch = 'Logistics'\nwhere branch is distinct from 'Logistics';\n\nalter table public.staff_profiles alter column display_name set default 'Staff IMEX';\nalter table public.staff_profiles alter column branch set default 'Logistics';\n\n-- Le site V6 ouvre uniquement des dossiers logistics.\n-- On garde la valeur corporate autorisée pour ne pas casser l'historique.\n\ncreate or replace function public.open_case(\n  p_kind text, p_service text, p_contact_name text, p_company_name text, p_phone text,\n  p_title text, p_description text, p_origin text default null, p_destination text default null,\n  p_cargo text default null, p_quantity text default null, p_requested_at timestamptz default null,\n  p_frequency text default null, p_urgency text default 'standard'\n) returns text language plpgsql security definer set search_path = public as $$\ndeclare v_id uuid; v_ref text;\nbegin\n  if p_kind <> 'logistics' then raise exception 'Type de dossier invalide'; end if;\n  if nullif(trim(p_service),'') is null or nullif(trim(p_contact_name),'') is null\n     or nullif(trim(p_phone),'') is null or nullif(trim(p_title),'') is null\n     or nullif(trim(p_description),'') is null then raise exception 'Champs obligatoires manquants'; end if;\n  loop\n    v_ref := 'IL-' || to_char(now(),'YYMMDD') || '-' || upper(substr(replace(gen_random_uuid()::text,'-',''),1,4));\n    exit when not exists(select 1 from public.cases where reference=v_ref);\n  end loop;\n  insert into public.cases(reference,kind,service,contact_name,company_name,phone,title,description,origin,destination,cargo,quantity,requested_at,frequency,urgency,status)\n  values(v_ref,'logistics',trim(p_service),trim(p_contact_name),nullif(trim(p_company_name),''),trim(p_phone),trim(p_title),trim(p_description),nullif(trim(p_origin),''),nullif(trim(p_destination),''),nullif(trim(p_cargo),''),nullif(trim(p_quantity),''),p_requested_at,nullif(trim(p_frequency),''),coalesce(nullif(trim(p_urgency),''),'standard'),'new')\n  returning id into v_id;\n  insert into public.case_messages(case_id,author_type,author_name,visibility,body)\n  values(v_id,'system','IMEX Logistics','public','Votre demande a bien été enregistrée. Notre équipe va l’étudier et vous répondra directement dans cet espace.');\n  return v_ref;\nend; $$;\n\nrevoke all on function public.open_case(text,text,text,text,text,text,text,text,text,text,text,timestamptz,text,text) from public;\ngrant execute on function public.open_case(text,text,text,text,text,text,text,text,text,text,text,timestamptz,text,text) to anon, authenticated;\n